//! Mintable CW721-like contract for Vegeta S3 NFT families.
use cosmwasm_std::{entry_point,to_json_binary,Addr,Binary,Deps,DepsMut,Env,MessageInfo,Response,StdError,StdResult};use cw_storage_plus::{Item,Map};use schemars::JsonSchema;use serde::{Deserialize,Serialize};use thiserror::Error;
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct InstantiateMsg{pub admin:String,pub name:String,pub symbol:String}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum ExecuteMsg{Mint{owner:String,token_id:Option<u64>,token_uri:Option<String>},TransferNft{recipient:String,token_id:u64},SendOrSafeTransferNft{recipient:String,token_id:u64},ApproveNft{spender:String,token_id:u64},ApproveAll{operator:String,approved:bool}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum QueryMsg{OwnerOf{token_id:u64},TokensByOwnerCount{owner:String},Approved{token_id:u64}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct Config{pub admin:Addr,pub name:String,pub symbol:String,pub next_token_id:u64}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct OwnerResponse{pub owner:String}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct CountResponse{pub count:u64}
const CONFIG:Item<Config>=Item::new("config");const OWNER:Map<u64,Addr>=Map::new("owner");const APPROVAL:Map<u64,Addr>=Map::new("approval");const OPERATORS:Map<(&str,&str),bool>=Map::new("operators");const OWNER_COUNT:Map<&str,u64>=Map::new("owner_count");const TOKEN_URI:Map<u64,String>=Map::new("token_uri");
#[derive(Error,Debug,PartialEq)]pub enum ContractError{#[error("{0}")]Std(#[from]StdError),#[error("unauthorized")]Unauthorized,#[error("token not found")]NotFound}
#[entry_point]pub fn instantiate(deps:DepsMut,_:Env,_:MessageInfo,msg:InstantiateMsg)->Result<Response,ContractError>{CONFIG.save(deps.storage,&Config{admin:deps.api.addr_validate(&msg.admin)?,name:msg.name,symbol:msg.symbol,next_token_id:1})?;Ok(Response::new())}
#[entry_point]pub fn execute(deps:DepsMut,_:Env,info:MessageInfo,msg:ExecuteMsg)->Result<Response,ContractError>{match msg{ExecuteMsg::Mint{owner,token_id,token_uri}=>mint(deps,info.sender,owner,token_id,token_uri),ExecuteMsg::TransferNft{recipient,token_id}|ExecuteMsg::SendOrSafeTransferNft{recipient,token_id}=>transfer(deps,info.sender,recipient,token_id),ExecuteMsg::ApproveNft{spender,token_id}=>approve(deps,info.sender,spender,token_id),ExecuteMsg::ApproveAll{operator,approved}=>{let o=deps.api.addr_validate(&operator)?;OPERATORS.save(deps.storage,(info.sender.as_str(),o.as_str()),&approved)?;Ok(Response::new())}}}
fn mint(deps:DepsMut,sender:Addr,owner:String,token_id:Option<u64>,uri:Option<String>)->Result<Response,ContractError>{let mut c=CONFIG.load(deps.storage)?;if c.admin!=sender{return Err(ContractError::Unauthorized)};let id=token_id.unwrap_or(c.next_token_id);let owner=deps.api.addr_validate(&owner)?;OWNER.save(deps.storage,id,&owner)?;if let Some(uri)=uri{TOKEN_URI.save(deps.storage,id,&uri)?;}OWNER_COUNT.update(deps.storage,owner.as_str(),|x|->StdResult<_>{Ok(x.unwrap_or_default()+1)})?;if id>=c.next_token_id{c.next_token_id=id+1;CONFIG.save(deps.storage,&c)?;}Ok(Response::new())}
fn authorized(deps:Deps,sender:&Addr,id:u64)->Result<Addr,ContractError>{let owner=OWNER.may_load(deps.storage,id)?.ok_or(ContractError::NotFound)?;if owner==*sender{return Ok(owner)};if APPROVAL.may_load(deps.storage,id)?.as_ref()==Some(sender){return Ok(owner)};if OPERATORS.may_load(deps.storage,(owner.as_str(),sender.as_str()))?.unwrap_or(false){return Ok(owner)};Err(ContractError::Unauthorized)}
fn transfer(deps:DepsMut,sender:Addr,recipient:String,id:u64)->Result<Response,ContractError>{let old=authorized(deps.as_ref(),&sender,id)?;let new=deps.api.addr_validate(&recipient)?;OWNER.save(deps.storage,id,&new)?;APPROVAL.remove(deps.storage,id);OWNER_COUNT.update(deps.storage,old.as_str(),|x|->StdResult<_>{Ok(x.unwrap_or_default().saturating_sub(1))})?;OWNER_COUNT.update(deps.storage,new.as_str(),|x|->StdResult<_>{Ok(x.unwrap_or_default()+1)})?;Ok(Response::new())}
fn approve(deps:DepsMut,sender:Addr,spender:String,id:u64)->Result<Response,ContractError>{let owner=OWNER.may_load(deps.storage,id)?.ok_or(ContractError::NotFound)?;if owner!=sender&&!OPERATORS.may_load(deps.storage,(owner.as_str(),sender.as_str()))?.unwrap_or(false){return Err(ContractError::Unauthorized)};APPROVAL.save(deps.storage,id,&deps.api.addr_validate(&spender)?)?;Ok(Response::new())}
#[entry_point]pub fn query(deps:Deps,_:Env,msg:QueryMsg)->StdResult<Binary>{match msg{QueryMsg::OwnerOf{token_id}=>to_json_binary(&OwnerResponse{owner:OWNER.load(deps.storage,token_id)?.into_string()}),QueryMsg::TokensByOwnerCount{owner}=>to_json_binary(&CountResponse{count:OWNER_COUNT.may_load(deps.storage,&owner)?.unwrap_or_default()}),QueryMsg::Approved{token_id}=>to_json_binary(&APPROVAL.may_load(deps.storage,token_id)?.map(Addr::into_string))}}
#[cfg(test)]mod tests{use super::*;use cosmwasm_std::testing::{mock_dependencies,mock_env,mock_info};#[test]fn mint_and_transfer_move_owner_key(){let mut d=mock_dependencies();instantiate(d.as_mut(),mock_env(),mock_info("x",&[]),InstantiateMsg{admin:"admin".into(),name:"N".into(),symbol:"N".into()}).unwrap();execute(d.as_mut(),mock_env(),mock_info("admin",&[]),ExecuteMsg::Mint{owner:"alice".into(),token_id:Some(7),token_uri:None}).unwrap();execute(d.as_mut(),mock_env(),mock_info("alice",&[]),ExecuteMsg::TransferNft{recipient:"bob".into(),token_id:7}).unwrap();assert_eq!(OWNER.load(d.as_ref().storage,7).unwrap(),Addr::unchecked("bob"));}}
